using UnityEngine.InputSystem.LowLevel;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
using Object=UnityEngine.Object;
[InitializeOnLoad]public static class GridShiftV7Checks {
 static GridShiftV7Checks(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("V7Core",false)){SessionState.SetBool("V7Core",false);var go=new GameObject("Operations7Checks");Object.DontDestroyOnLoad(go);go.AddComponent<GridShiftV7PlayChecks>();}};}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){if(SessionState.GetBool("V7Core",false)){DeliverySaveStore.OverridePath=Path.GetFullPath("v7-core-save.json");GridShiftControls.Prefix="GS.Test7.Keys.";GridShiftControls.Reset();GridShiftTutorial.Prefix="GS.Test7.Tutorial.";GridShiftTutorial.Reopen();}}
 public static void Batch(){EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");foreach(var w in Object.FindObjectsByType<ClimaReal>(FindObjectsSortMode.None))w.enabled=false;foreach(var c in Object.FindObjectsByType<Camera>(FindObjectsSortMode.None))c.enabled=false;SessionState.SetBool("V7Core",true);EditorApplication.isPlaying=true;}
}
public sealed class GridShiftV7PlayChecks:MonoBehaviour {
 StringBuilder report=new StringBuilder();List<string> errors=new List<string>();Keyboard keyboard;List<InputDevice> disabled=new List<InputDevice>();DeliveryManager manager;PlayerMovement player;
 void Check(bool ok,string text){if(!ok)throw new Exception(text);report.AppendLine("PASS "+text);File.WriteAllText("v7-core-progress.txt",report.ToString());}
 void Log(string text,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception)errors.Add(text);}
 void Current(){keyboard.MakeCurrent();}void Loaded(Scene scene,LoadSceneMode mode){foreach(var root in scene.GetRootGameObjects()){foreach(var w in root.GetComponentsInChildren<ClimaReal>(true))w.enabled=false;foreach(var c in root.GetComponentsInChildren<Camera>(true))c.enabled=false;}}
 IEnumerator Start(){Application.runInBackground=true;Application.targetFrameRate=60;Application.logMessageReceived+=Log;SceneManager.sceneLoaded+=Loaded;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;foreach(var d in InputSystem.devices.ToArray())if(d is Keyboard){InputSystem.DisableDevice(d);disabled.Add(d);}keyboard=InputSystem.AddDevice<Keyboard>();InputSystem.onAfterUpdate+=Current;var routines=new Stack<IEnumerator>();routines.Push(Run());bool success=true;while(routines.Count>0){object value=null;bool more;try{more=routines.Peek().MoveNext();if(more)value=routines.Peek().Current;}catch(Exception e){success=false;report.AppendLine("FAIL "+e);break;}if(!more){routines.Pop();continue;}if(value is IEnumerator nested&&!(value is CustomYieldInstruction)){routines.Push(nested);continue;}yield return value;}InputSystem.onAfterUpdate-=Current;InputSystem.RemoveDevice(keyboard);foreach(var d in disabled)if(d.added)InputSystem.EnableDevice(d);Application.logMessageReceived-=Log;SceneManager.sceneLoaded-=Loaded;Time.timeScale=1;success&=errors.Count==0;report.AppendLine("Erros: "+string.Join("; ",errors));report.AppendLine("RESULT "+(success?"SUCCESS":"FAILURE"));File.WriteAllText("v7-core.txt",report.ToString());EditorApplication.Exit(success?0:1);}
 IEnumerator Until(Func<bool> condition,float seconds,string label){float end=Time.realtimeSinceStartup+seconds;while(!condition()&&Time.realtimeSinceStartup<end)yield return null;if(!condition())throw new Exception("Timeout "+label);}
 IEnumerator Tap(Key key){InputSystem.QueueStateEvent(keyboard,new KeyboardState(key));yield return null;yield return null;InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return null;yield return null;}
 DeliveryOrder Create(float weight,CompanyVehicle vehicle){var points=manager.points.Where(p=>p.Valid&&manager.Progression.Unlocked(p));var pickup=points.Where(p=>DeliveryRouting.Find(vehicle.driver.RotaAtual,p.route,DeliveryRouting.Behind(vehicle.driver,p))!=null).OrderBy(p=>DeliveryRouting.Find(vehicle.driver.RotaAtual,p.route,DeliveryRouting.Behind(vehicle.driver,p)).Sum(DeliveryRouting.Length)).First();var destination=points.Where(p=>p!=pickup&&DeliveryRouting.Find(pickup.route,p.route)!=null).OrderBy(p=>DeliveryRouting.Find(pickup.route,p.route).Sum(DeliveryRouting.Length)).First();Check(manager.TryCreate(new DeliveryRequest{goods="Validação 7 "+weight,weightKg=weight,pickupId=pickup.id,destinationId=destination.id},out var order,out var error),"criar "+weight+" kg: "+error);return order;}
 IEnumerator Run(){yield return new WaitForSecondsRealtime(3);manager=DeliveryManager.Instance;player=Object.FindFirstObjectByType<PlayerMovement>();var ui=GridShiftOperationsUI.Instance;Check(manager!=null&&ui!=null,"sistemas existentes e nova interface inicializados");Check(manager.points.Count(p=>p.Valid)>31&&manager.points.Select(p=>p.id).Distinct().Count()==manager.points.Length,"catálogo ampliado com IDs únicos");Check(manager.points.Where(p=>p.Valid).All(p=>DeliveryRouting.Find(manager.points[0].route,p.route)!=null),"novos locais conectados ao grafo real");Check(manager.points.Any(p=>p.requiredExpansion>0),"parceiros bloqueados por progressão");Check(!manager.Progression.Buy("capacity",out _),"saldo insuficiente não permite comprar upgrade");Check(!manager.Progression.Buy("profit",out _),"pré-requisito de contratos melhores respeitado");
  yield return Until(()=>manager.fleet.Count==3,20,"frota inicial");var cars=manager.fleet.Where(v=>v.kind==FleetKind.Car).ToArray();var truck=manager.fleet.First(v=>v.kind==FleetKind.Truck);var a=Create(5,cars[0]);var b=Create(50,cars[1]);var c=Create(500,truck);manager.Dispatch();Check(a.vehicleId!=null&&b.vehicleId!=null&&c.vehicleId==truck.id,"5 e 50 kg em carros e 500 kg no caminhão");Check(manager.Offers().Select(o=>o.kind).Distinct().Count()==6,"seis modalidades disponíveis com destinos válidos");var offer=manager.Offers().First();int count=manager.orders.Count;Check(manager.Accept(offer.id,out _)&&manager.Accept(offer.id,out _)&&manager.orders.Count==count+1,"aceitar oferta é idempotente");manager.Dispatch();Check(manager.fleet.Count(v=>v.Order!=null)<=3,"despacho respeita simultaneidade inicial");
  manager.RestoreEconomy(2500,manager.orders,manager.SelectedId);float money=manager.Money;Check(manager.Progression.Buy("capacity",out _)&&Mathf.Abs(manager.Money-(money-120))<.01f&&truck.capacityKg==3125,"upgrade de capacidade cobra saldo e aplica efeito real");Check(manager.Progression.Buy("handling",out _)&&manager.Progression.Handling<1,"doca reduz tempo de operação");Check(manager.Progression.Buy("profit",out _)&&manager.Progression.Profit>1,"pré-requisito libera bônus para novos pedidos");int accessible=manager.points.Count(p=>p.Valid&&manager.Progression.Unlocked(p));Check(manager.Progression.Buy("district",out _)&&manager.points.Count(p=>p.Valid&&manager.Progression.Unlocked(p))>accessible,"rede de parceiros libera locais reais");Check(manager.Progression.Buy("fleet",out _),"compra de vaga na frota");Check(manager.Progression.Buy("dispatch",out _)&&manager.Progression.Concurrent==5,"central aumenta limite simultâneo");yield return Until(()=>manager.fleet.Count==4,20,"carro adicional adotado do tráfego");Check(manager.fleet.All(v=>manager.traffic.Vehicles.Contains(v.driver)),"frota ampliada reutiliza veículos existentes");
  yield return Tap(Key.M);Check(ui.Current=="map"&&player.ControlsBlocked,"M abre mapa e bloqueia movimento");Check(player.GetComponentsInChildren<CanvasGroup>().All(g=>g.alpha==0),"interfaces modais ocultam HUD do avatar sem duplicação");yield return Tap(Key.G);Check(!player.GetComponent<PortableTablet>().IsOpen,"G não abre tablet sobre mapa");yield return Tap(Key.M);Check(ui.Current==null&&!player.ControlsBlocked,"M reduz mapa e devolve controles");yield return Tap(Key.F2);Check(ui.Current=="controls","F2 abre controles");Check(!GridShiftControls.Rebind(GSAction.Forward,Key.S,out _),"conflito de tecla recusado");ui.BeginRebind(GSAction.Forward);yield return Tap(Key.K);Check(GridShiftControls.Binding(GSAction.Forward)==Key.K&&!GridShiftControls.Capturing,"captura salva nova tecla sem acionar jogo");GridShiftControls.Reload();Check(GridShiftControls.Binding(GSAction.Forward)==Key.K,"remapeamento sobrevive à releitura das preferências");yield return Tap(Key.Escape);Check(ui.Current==null&&!PauseMenu.Instance.IsOpen,"ESC fecha controles antes de pausa");InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.K));yield return null;yield return null;Check(player.MovementInput.y>0,"movimentação usa tecla remapeada");InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return null;GridShiftControls.Reset();Check(GridShiftControls.Binding(GSAction.Forward)==Key.W,"restaurar padrão funciona");
  yield return Tap(Key.M);yield return Tap(Key.Escape);Check(ui.Current==null&&!PauseMenu.Instance.IsOpen,"ESC fecha mapa sem abrir pausa no mesmo quadro");yield return Tap(Key.Escape);Check(PauseMenu.Instance.IsOpen,"ESC seguinte abre pausa");ui.Open("controls",true);yield return Tap(Key.Escape);Check(PauseMenu.Instance.IsOpen&&ui.Current==null,"controles da pausa retornam à pausa");yield return Tap(Key.Escape);Check(!PauseMenu.Instance.IsOpen,"pausa retorna ao jogo");
  GridShiftTutorial.Reopen();ui.Open("tutorial");Check(ui.Current=="tutorial"&&player.ControlsBlocked,"tutorial pode ser reaberto e recebe foco");GridShiftTutorial.Next();Check(GridShiftTutorial.Step==1,"etapa avançada salva");GridShiftTutorial.Skip();ui.Close();Check(GridShiftTutorial.Skipped&&!GridShiftTutorial.Completed,"pular tutorial preserva preferência");GridShiftTutorial.Reopen();for(int i=0;i<10;i++)GridShiftTutorial.Next();Check(GridShiftTutorial.Completed,"tutorial completo registrado");
  var mm=player.GetComponentInChildren<MinimapCamera>(true).GetComponent<Camera>();int forbidden=(1<<5)|(1<<7)|(1<<8)|(1<<10)|(1<<LayerMask.NameToLayer("DeliveryWorld"));Check((mm.cullingMask&forbidden)==0,"minimapa exclui HUD 3D, corpos e marcadores físicos");yield return null;Check(manager.GetComponentsInChildren<MeshRenderer>().Length==0,"sem setas gigantes de malha 3D no minimapa");Check(Object.FindObjectsByType<GridShiftMapMarkers>(FindObjectsSortMode.None).Length>0,"ícones UI do mapa ligados à câmera real");
  DeliverySaveData save=null;Check(manager.GetComponent<DeliveryPersistence>().Save()&&DeliverySaveStore.Read(out save)&&save.upgrades.Count>=6,"upgrades e pedidos integrados ao salvamento");var beforeLevels=manager.Progression.Level("capacity");manager.Progression.Restore(save.upgrades);Check(manager.Progression.Level("capacity")==beforeLevels&&truck.capacityKg==3125,"efeitos de upgrades restaurados sem duplicar níveis");
  Time.timeScale=5;var world=WorldSession.Instance;int identity=manager.GetInstanceID();world.RequestTransition("Office",player.transform);yield return Until(()=>!world.Busy,30,"Office");yield return new WaitForSeconds(15);Check(DeliveryManager.Instance.GetInstanceID()==identity&&manager.Progression.Level("capacity")==1,"Office preserva empresa e upgrades");var office=Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None).First(p=>p.gameObject.scene.name=="Office");world.RequestTransition("SampleScene",office.transform);yield return Until(()=>!world.Busy,30,"retorno");yield return Until(()=>a.status==DeliveryStatus.Completed&&b.status==DeliveryStatus.Completed&&c.status==DeliveryStatus.Completed,350,"três entregas físicas após melhorias");Check(a.rewardPaid&&b.rewardPaid&&c.rewardPaid,"conclusões legítimas creditadas após mudanças");float finalMoney=manager.Money;manager.Complete(c);Check(manager.Money==finalMoney,"pagamento único preservado");for(int i=0;i<5;i++){var pendingOffer=manager.Offers().First();Check(manager.Accept(pendingOffer.id,out _),"aceitar restante do lote de contratos");}Check(manager.Offers().Count==6&&manager.Offers().All(o=>o.id.StartsWith("OF-1-")),"contratos renovam em novo lote sem repetir IDs aceitos");Check(manager.GetComponent<DeliveryPersistence>().Save(),"salvar operação após conclusão");
 }
}
